/**
 * V14 — "Jungla de Xeno, sin escapatoria" (owner request, 17-nov-2026). Same jungle, beings, orders and look-alikes
 * as V13 (the trials are V13's, generated by the same function), with three rule changes:
 *  - A screen stays until every being with the ordered trait has been taken down: no deadline and no "three wrongs
 *    and out". The clock keeps running, so the only way to a good time is to clear the screen.
 *  - Shooting a being that was not ordered (+400 ms, as before) sends it back into hiding and makes a NEW target come
 *    out at another free hiding place. Spraying taps therefore costs time twice and can never clear a screen faster.
 *  - A tap before the beings come out (+600 ms, as before) no longer skips the screen.
 * Only as a guard against an abandoned run, a screen closes after `roundSafetyTicks` (30 s) with the usual penalty for
 * every target left standing. Score: accumulated ms (lower is better); `height` mirrors it for V1 duels.
 * Actions: PICK_n taps the being at hiding place n (0–9), so spawned targets need no new action names.
 * V1–V13 stay frozen.
 */
import { createRng } from "../deterministic/seeded";
import type { CoreState, GameCore } from "./coreRuntime.v1";
import { SHOT_GALLERY_ACTIONS_V3 } from "./shotGalleryProtocol.v3";
import {
  GALLERY_V13,
  GALLERY_V13_AURAS,
  GALLERY_V13_FORMS,
  galleryMatchesV13,
  galleryTicksToMsV13,
  galleryTrialsV13,
  type GalleryBeingV13,
  type GalleryOrderV13,
  type GalleryTrialV13,
} from "./shotGalleryCore.v13";

export const GALLERY_V14_AURAS = GALLERY_V13_AURAS;
export const GALLERY_V14_FORMS = GALLERY_V13_FORMS;
export const galleryMatchesV14 = galleryMatchesV13;
export const galleryTicksToMsV14 = galleryTicksToMsV13;
export const GALLERY_V14 = Object.freeze({
  ...GALLERY_V13,
  /** Guard against an abandoned run only: a screen closes after 30 s. */
  roundSafetyTicks: 3600,
});
export type GalleryOrderV14 = GalleryOrderV13;
export type GalleryTrialV14 = GalleryTrialV13;
/** A being on the current screen. `born` is the tick a spawned target starts coming out (-1: with the screen);
 * `gone` the tick a wrongly shot being went back into hiding (-1: still out). */
export type GalleryBeingV14 = GalleryBeingV13 & { target: boolean; born: number; gone: number };
export type GalleryResultV14 = {
  trial: number;
  type: "CORRECT" | "TIMEOUT";
  taps: number[];
  wrongs: number;
  falseStarts: number;
  /** Targets that came out after a wrong shot. */
  spawned: number;
  addedMs: number;
};
export type GalleryStateV14 = CoreState & {
  seed: string;
  trials: GalleryTrialV14[];
  trial: number;
  phase: "waiting" | "ready" | "feedback";
  phaseTicks: number;
  readyTick: number;
  /** The beings of the current screen (the trial's beings plus spawned targets). */
  live: GalleryBeingV14[];
  /** Indices into `live` of the targets taken down, in order. */
  hits: number[];
  tapTicks: number[];
  wrongs: number;
  falseStarts: number;
  spawned: number;
  /** Index into `live` of the last tap (-1 for a tap before the beings came out). */
  lastPick: number;
  lastTapTick: number;
  tapTickAbs: number;
  lastAddedMs: number;
  results: GalleryResultV14[];
  totalMs: number;
  roundMs: number;
  correct: number;
};

const beingsOf = (trial: GalleryTrialV14): GalleryBeingV14[] =>
  trial.targets.map((b, i) => ({ ...b, target: trial.answers.includes(i), born: -1, gone: -1 }));

export function createGalleryV14(seed: string): GalleryStateV14 {
  const trials = galleryTrialsV13(seed);
  return {
    tick: 0, status: "running", failure: null, score: 0, seed, trials, trial: 0,
    phase: "waiting", phaseTicks: 0, readyTick: -1, live: beingsOf(trials[0]), hits: [], tapTicks: [], wrongs: 0,
    falseStarts: 0, spawned: 0, lastPick: -1, lastTapTick: -999, tapTickAbs: -1, lastAddedMs: 0, results: [],
    totalMs: 0, roundMs: 0, correct: 0,
  };
}

/** Targets still to take down on this screen. */
export const galleryRemainingV14 = (s: GalleryStateV14) => s.live.filter((b, i) => b.target && !s.hits.includes(i)).length;
/** The being out at hiding place `spot` (not hit, not gone), or -1. */
export const galleryAtSpotV14 = (s: GalleryStateV14, spot: number) =>
  s.live.findIndex((b, i) => b.spot === spot && b.gone < 0 && !s.hits.includes(i));

function add(s: GalleryStateV14, ms: number) {
  s.totalMs += ms;
  s.roundMs += ms;
}
function resetRound(s: GalleryStateV14) {
  s.hits = []; s.tapTicks = []; s.wrongs = 0; s.falseStarts = 0; s.spawned = 0; s.roundMs = 0;
}
function resolve(s: GalleryStateV14, type: GalleryResultV14["type"]) {
  if (type === "TIMEOUT") add(s, galleryRemainingV14(s) * GALLERY_V14.missedPlatePenaltyMs);
  else s.correct++;
  s.results.push({ trial: s.trial, type, taps: [...s.tapTicks], wrongs: s.wrongs, falseStarts: s.falseStarts, spawned: s.spawned, addedMs: s.roundMs });
  s.phase = "feedback";
  s.phaseTicks = 0;
}

/** A new target with the ordered trait at a free hiding place other than `notSpot` (deterministic per seed, screen
 * and wrong shot). The other trait is free, as for the screen's own targets. */
function spawnTarget(s: GalleryStateV14, notSpot: number) {
  const trial = s.trials[s.trial];
  const rng = createRng(`${s.seed}:gallery14:spawn:${s.trial}:${s.spawned}`);
  for (let k = 0; k < GALLERY_V14.rngWarmup; k++) rng.nextUint();
  const busy = new Set(s.live.filter((b, i) => b.gone < 0 && !s.hits.includes(i)).map((b) => b.spot));
  let free = GALLERY_V14.spots.map((_, n) => n).filter((n) => !busy.has(n) && n !== notSpot);
  if (!free.length) free = [notSpot];
  const spot = free[rng.nextInt(free.length)];
  const where = GALLERY_V14.spots[spot], o = trial.order;
  const being: GalleryBeingV14 = o.kind === "AURA"
    ? { ...where, spot, aura: o.value, form: rng.nextInt(GALLERY_V14_FORMS.length), lookalike: false, target: true, born: s.tick, gone: -1 }
    : { ...where, spot, form: o.value, aura: rng.nextInt(GALLERY_V14_AURAS.length), lookalike: false, target: true, born: s.tick, gone: -1 };
  s.live.push(being);
  s.spawned++;
}

export function stepGalleryV14(s: GalleryStateV14) {
  s.tick++;
  s.phaseTicks++;
  const trial = s.trials[s.trial];
  if (s.phase === "waiting") {
    if (s.phaseTicks >= trial.waitTicks) { s.phase = "ready"; s.phaseTicks = 0; s.readyTick = s.tick; }
    return;
  }
  if (s.phase === "ready") {
    if (s.phaseTicks >= GALLERY_V14.roundSafetyTicks) resolve(s, "TIMEOUT");
    return;
  }
  if (s.phaseTicks < GALLERY_V14.feedbackTicks) return;
  s.trial++;
  if (s.trial === GALLERY_V14.trials) {
    s.status = "won";
    s.failure = null;
    s.score = s.totalMs;
    s.height = Math.max(0, GALLERY_V14.reachBase - s.totalMs);
    return;
  }
  s.phase = "waiting"; s.phaseTicks = 0; s.readyTick = -1; s.live = beingsOf(s.trials[s.trial]); resetRound(s);
}

export function canApplyGalleryV14(s: GalleryStateV14, a: string) {
  if (s.status !== "running" || s.phase === "feedback" || !SHOT_GALLERY_ACTIONS_V3.includes(a)) return false;
  if (s.phase === "waiting") return true;
  const spot = Number(a.slice(5));
  return spot < GALLERY_V14.spots.length && galleryAtSpotV14(s, spot) >= 0;
}

export function applyGalleryV14(s: GalleryStateV14, a: string) {
  s.lastTapTick = s.tick;
  if (s.phase === "waiting") {
    // Too early: penalised, but the screen still has to be cleared.
    s.falseStarts++;
    s.lastPick = -1;
    s.lastAddedMs = GALLERY_V14.falseStartPenaltyMs;
    add(s, GALLERY_V14.falseStartPenaltyMs);
    return;
  }
  const i = galleryAtSpotV14(s, Number(a.slice(5))), b = s.live[i];
  s.lastPick = i;
  if (b.target) {
    const ms = galleryTicksToMsV14(s.tick - (s.hits.length ? s.tapTickAbs : s.readyTick));
    s.hits.push(i);
    s.tapTicks.push(s.tick - s.readyTick);
    s.tapTickAbs = s.tick;
    s.lastAddedMs = ms;
    add(s, ms);
    if (galleryRemainingV14(s) === 0) resolve(s, "CORRECT");
    return;
  }
  s.wrongs++;
  s.lastAddedMs = GALLERY_V14.wrongPenaltyMs;
  add(s, GALLERY_V14.wrongPenaltyMs);
  b.gone = s.tick;
  spawnTarget(s, b.spot);
}

export const SHOT_GALLERY_CORE_V14: GameCore<GalleryStateV14> = {
  gameId: "reaction-test",
  gameVersion: "14.0.0",
  width: 390,
  height: 620,
  tickRate: 120,
  maxFinalTick: 120 * 60 * 7,
  maxInputs: 400,
  inputVersion: 3,
  actions: SHOT_GALLERY_ACTIONS_V3,
  content: {
    rules: GALLERY_V14,
    auras: GALLERY_V14_AURAS,
    forms: GALLERY_V14_FORMS,
    scenario: "gallery14-xeno-jungle-clear-every-target-wrong-shot-spawns-a-target",
    clock: "TICKS_POPUP_THEN_REACTION_UNTIL_CLEARED",
    aggregation: "ACCUMULATED_REACTION_MS_PUBLISHED_AT_TERMINAL_LOWER_IS_BETTER",
    picks: "PICK_n_IS_HIDING_PLACE_n",
  },
  create: createGalleryV14,
  step: stepGalleryV14,
  canApply: canApplyGalleryV14,
  apply: applyGalleryV14,
};
